import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Attributes and Skills","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/accessory/integration.md","filePath":"en/modules/accessory/integration.md","lastUpdated":0}`),a={name:`en/modules/accessory/integration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="attributes-and-skills" tabindex="-1">Attributes and Skills <a class="header-anchor" href="#attributes-and-skills" aria-label="Permalink to “Attributes and Skills”">​</a></h1><p>Accessory attributes and skills are not computed by EmakiAccessory itself; they are registered into the public extension points of EmakiAttribute and EmakiSkills. Both are optional dependencies, so the corresponding half simply switches off when one is absent while the accessory panel keeps working.</p><h2 id="attributes-into-emakiattribute" tabindex="-1">Attributes into EmakiAttribute <a class="header-anchor" href="#attributes-into-emakiattribute" aria-label="Permalink to “Attributes into EmakiAttribute”">​</a></h2><p>EmakiAccessory registers a <strong>contribution provider</strong> with EmakiAttribute, feeding accessory attributes in as a distinct source. It registers no custom equipment slot and writes nothing onto the player&#39;s vanilla attributes.</p><p>The reported source ids:</p><table tabindex="0"><thead><tr><th>Source id</th><th>Meaning</th></tr></thead><tbody><tr><td><code>emakiaccessory:accessory</code></td><td>Attributes of an individual accessory.</td></tr><tr><td><code>emakiaccessory:set</code></td><td>Accessory set bonuses.</td></tr></tbody></table><p>Attribute values are read through EmakiAttribute&#39;s <code>AttributeCatalog#itemSnapshot</code> — <strong>the same parser the equipment path uses</strong>. An accessory and a helmet carrying identical data therefore produce identical numbers, and parent-attribute expansion plus range-spread companion keys come along with it.</p><p>Range-spread companion keys are summed like any other key; otherwise a ranged accessory would keep its lower bound and lose its spread.</p><h2 id="skills-into-emakiskills" tabindex="-1">Skills into EmakiSkills <a class="header-anchor" href="#skills-into-emakiskills" aria-label="Permalink to “Skills into EmakiSkills”">​</a></h2><p>EmakiAccessory registers a <strong>skill source</strong> with EmakiSkills. Equipment skill payloads on an accessory are read by <code>EquipmentSkillPdcCodec</code>, the same PDC contract Item, Forge, Gem and Strengthen write.</p><p>Skills listed in an accessory set&#39;s <code>thresholds[].effects[].es_skills</code> take effect through that same path.</p><h2 id="slot-restriction-criterion" tabindex="-1">Slot Restriction Criterion <a class="header-anchor" href="#slot-restriction-criterion" aria-label="Permalink to “Slot Restriction Criterion”">​</a></h2><p>Accessories support <code>active_slot</code> declarations just like equipment. The accessory-side matching rule:</p><table tabindex="0"><thead><tr><th>The item&#39;s <code>active_slot</code></th><th>Result</th></tr></thead><tbody><tr><td>Absent or &quot;all&quot;</td><td>Active in any accessory slot.</td></tr><tr><td>A part id, such as <code>ring</code></td><td>Active in any cell of that part.</td></tr><tr><td>A slot instance id, such as <code>ring_1</code></td><td>Active only in that cell.</td></tr><tr><td>Anything else</td><td>Inactive.</td></tr></tbody></table><p>When an item declares several slots, <strong>every declaration must be satisfied by the current cell</strong>, otherwise the whole item&#39;s contribution is dropped. This matches the equipment path&#39;s behaviour of dropping the whole item&#39;s contribution when a declared slot does not match.</p><p>The accessory-side gate is a <strong>separate implementation</strong> because <code>itemSnapshot</code> performs no slot filtering while the equipment path&#39;s own gate is internal to EmakiAttribute. The accessory side additionally accepts a bare part id. If the equipment-side rules ever change, this copy must be updated to match.</p><h2 id="when-recomputation-happens" tabindex="-1">When Recomputation Happens <a class="header-anchor" href="#when-recomputation-happens" aria-label="Permalink to “When Recomputation Happens”">​</a></h2><p>Contribution snapshots are recomputed when accessory contents change: a GUI edit, a completed data load, or a reload.</p><p>Recomputation deliberately <strong>does not happen inside the provider callback</strong>. EmakiAttribute&#39;s combat snapshot collector calls the contribution provider while computing its cache signature, meaning the provider runs on every combat snapshot read; parsing PDC there would put item deserialisation on the combat hot path.</p><h2 id="threading" tabindex="-1">Threading <a class="header-anchor" href="#threading" aria-label="Permalink to “Threading”">​</a></h2><p>Recomputation must run on the owner thread of the player holding the items: the attribute parser writes its result back into item PDC as a cache, so it is not safe off-thread.</p><h2 id="behaviour-with-modules-missing" tabindex="-1">Behaviour With Modules Missing <a class="header-anchor" href="#behaviour-with-modules-missing" aria-label="Permalink to “Behaviour With Modules Missing”">​</a></h2><table tabindex="0"><thead><tr><th>Missing module</th><th>Effect</th></tr></thead><tbody><tr><td>EmakiAttribute</td><td>Accessories grant no attributes; the panel and set piece counting keep working.</td></tr><tr><td>EmakiSkills</td><td>Accessories grant no skills.</td></tr><tr><td>EmakiItem</td><td><code>unique</code> deduplication falls back to vanilla material matching and stays active; accessory sets relying on <code>pieces[].item</code> are entirely inactive.</td></tr><tr><td>PlaceholderAPI</td><td>PAPI placeholders in text are no longer replaced and pass through unchanged.</td></tr></tbody></table><p>EmakiAccessory itself has <strong>no</strong> PlaceholderAPI expansion and exposes no <code>%emakiaccessory_*%</code> placeholders; it only consumes PlaceholderAPI optionally. The module also registers <strong>no</strong> actions into the CoreLib action registry.</p>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};